# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# surplus_production ----
## Setup ----
# A 3-year Schaefer model with r = 0.5, K = 100 and P_1 = 1, and catches of
# 10, 20 and 15. By hand:
# P_2 = 1 + 0.5 * 1 * (1 - 1) - 10 / 100 = 0.9
# P_3 = 0.9 + 0.5 * 0.9 * (1 - 0.9) - 20 / 100 = 0.745
# P_4 = 0.745 + 0.5 * 0.745 * (1 - 0.745) - 15 / 100 = 0.6899875
# The index is q * K * P_t with q = 0.5.
hand_depletion <- c(1, 0.9, 0.745, 0.6899875)
small_data <- data.frame(
  type = rep(c("catch", "index"), each = 3),
  fleet = rep(c("fleet1", "survey1"), each = 3),
  age = NA_real_,
  length = NA_real_,
  timing = rep(2001:2003, 2),
  observed = c(10, 20, 15, 0.5 * 100 * hand_depletion[1:3]),
  unit = "mt",
  uncertainty = rep(
    c(NA, "~ dlnorm(meanlog = log_index_expected, sdlog = 0.2)"),
    each = 3
  )
)
small_frame <- FIMSFrame(small_data)
# The process values are the hand-calculated log depletion, so there is no
# process error.
small_parameters <- setup_default_parameters(
  small_frame,
  model_type = "SurplusProduction"
) |>
  dplyr::rows_update(
    tibble::tibble(
      label = c("log_growth_rate", "log_carrying_capacity"),
      value = log(c(0.5, 100))
    ),
    by = "label"
  ) |>
  dplyr::rows_update(
    tibble::tibble(
      label = "log_depletion",
      timing = 2002:2003,
      value = log(hand_depletion[2:3])
    ),
    by = c("label", "timing")
  )

## IO correctness ----
test_that("`surplus_production()` works with correct inputs", {
  fit <- small_parameters |>
    initialize_fims(data = small_frame) |>
    fit_fims(optimize = FALSE)
  report <- get_report(fit)
  # The smooth floor on expected depletion, ad_max(P, 0.001, C = 1e-8), adds
  # about 2.5e-9 / P, so values from the depletion equation are within 1e-8.
  #' @description Test that the expected depletion equals the hand-calculated depletion in years 2 and 3, so the process residuals are 0.
  expect_equal(
    object = exp(report[["log_expected_depletion"]]),
    expected = hand_depletion[2:3],
    tolerance = 1e-8
  )
  #' @description Test that depletion is the hand-calculated depletion, including the year after the last year, which has no process error.
  expect_equal(
    object = report[["depletion"]][[1]],
    expected = hand_depletion,
    tolerance = 1e-8
  )
  #' @description Test that biomass is K times depletion.
  expect_equal(
    object = report[["biomass"]][[1]],
    expected = 100 * hand_depletion,
    tolerance = 1e-8
  )
  #' @description Test that the harvest rate is catch over biomass at the start of the year.
  expect_equal(
    object = report[["harvest_rate"]][[1]],
    expected = c(10, 20, 15) / (100 * hand_depletion[1:3])
  )
  # For the Schaefer model, the harvest rate at MSY is r / 2, the biomass at
  # MSY is K / 2 and MSY is r K / 4.
  #' @description Test that the harvest rate at MSY, biomass at MSY and MSY are r / 2 = 0.25, K / 2 = 50 and r K / 4 = 12.5 for the Schaefer model.
  expect_equal(
    object = c(
      report[["harvest_rate_at_msy"]][[1]], report[["biomass_at_msy"]][[1]],
      report[["maximum_sustainable_yield"]][[1]]
    ),
    expected = c(0.25, 50, 12.5)
  )
  #' @description Test that catchability is 0.5 when the index is 0.5 times biomass.
  expect_equal(
    object = report[["catchability"]][[2]],
    expected = 0.5
  )
  #' @description Test that the expected index equals the observed index when the index is q times biomass.
  expect_equal(
    object = report[["index_expected"]][[2]],
    expected = small_data[["observed"]][4:6]
  )
  #' @description Test that a fleet with catch and no index has no index predictions.
  expect_length(report[["index_expected"]][[1]], 0)
  # The process residuals are 0, so each of the 2 process values adds
  # -log(dnorm(0, 0, 0.1)). The index residuals are 0 too.
  #' @description Test that the negative log-likelihood components are the process density at residuals of 0 and the lognormal index density at the observations.
  expect_equal(
    object = report[["nll_components"]],
    expected = c(
      -2 * stats::dnorm(0, 0, 0.1, log = TRUE),
      -sum(stats::dlnorm(
        small_data[["observed"]][4:6], log(small_data[["observed"]][4:6]),
        0.2,
        log = TRUE
      ))
    ),
    tolerance = 1e-8
  )
})

test_that("`surplus_production()` puts the MSY quantities at the peak of surplus production", {
  # At m = 2 the MSY formulas cannot be told apart from other formulas that
  # give the same 3 numbers, so the peak is also found numerically at m = 3
  # and m = 0.5. Catch is taken at the end of the year, so the harvest rate at
  # MSY is MSY over the biomass at MSY.
  for (shape in c(3, 0.5)) {
    report <- small_parameters |>
      dplyr::rows_update(
        tibble::tibble(label = "log_shape", value = log(shape)),
        by = "label"
      ) |>
      initialize_fims(data = small_frame) |>
      fit_fims(optimize = FALSE) |>
      get_report()
    production <- function(biomass) {
      0.5 / (shape - 1) * biomass * (1 - (biomass / 100)^(shape - 1))
    }
    peak <- stats::optimize(production, c(0, 100), maximum = TRUE, tol = 1e-10)
    #' @description Test that the biomass at MSY is where surplus production peaks.
    expect_equal(
      object = report[["biomass_at_msy"]][[1]],
      expected = peak[["maximum"]],
      tolerance = 1e-6
    )
    #' @description Test that MSY is the peak surplus production.
    expect_equal(
      object = report[["maximum_sustainable_yield"]][[1]],
      expected = peak[["objective"]],
      tolerance = 1e-6
    )
    #' @description Test that the harvest rate at MSY is MSY over the biomass at MSY.
    expect_equal(
      object = report[["harvest_rate_at_msy"]][[1]],
      expected = peak[["objective"]] / peak[["maximum"]],
      tolerance = 1e-6
    )
  }
})

test_that("`get_estimates()` labels the surplus production quantities", {
  estimates <- small_parameters |>
    initialize_fims(data = small_frame) |>
    fit_fims(optimize = FALSE) |>
    get_estimates()
  #' @description Test that the MSY quantities have 1 row each with no year.
  expect_equal(
    object = estimates |>
      dplyr::filter(label %in% c(
        "harvest_rate_at_msy", "biomass_at_msy", "maximum_sustainable_yield"
      )) |>
      dplyr::pull(year_i),
    expected = rep(NA_real_, 3)
  )
  #' @description Test that depletion has 1 row per year and the year after the last year.
  expect_equal(
    object = estimates |>
      dplyr::filter(label == "depletion") |>
      dplyr::pull(year_i),
    expected = 1:4
  )
  #' @description Test that catchability is a Fleet row of the index fleet.
  expect_equal(
    object = estimates |>
      dplyr::filter(label == "catchability") |>
      dplyr::select(module_name, fleet) |>
      as.list(),
    expected = list(module_name = "Fleet", fleet = "survey1")
  )
  #' @description Test that each log_depletion row has its expected value, the log of the expected depletion.
  expect_equal(
    object = estimates |>
      dplyr::filter(label == "log_depletion") |>
      dplyr::pull(expected) |>
      exp(),
    expected = hand_depletion[2:3],
    tolerance = 1e-8
  )
  #' @description Test that the process sd row is labeled log_depletion_log_sd.
  expect_true("log_depletion_log_sd" %in% estimates[["label"]])
})

## Edge handling ----
test_that("`surplus_production()` returns correct outputs for edge cases", {
  withr::local_options(rlib_message_verbosity = "default")
  # A catch larger than the biomass: 200 against a biomass of 100 gives an
  # expected depletion of 1 - 2 = -1, which the floor keeps near 0.001.
  large_catch_data <- dplyr::mutate(
    small_data,
    observed = dplyr::if_else(type == "catch" & timing == 2001, 200, observed)
  )
  fit <- small_parameters |>
    initialize_fims(data = FIMSFrame(large_catch_data)) |>
    fit_fims(optimize = FALSE)
  # ad_max(-1, 0.001, C = 1e-8) = (-0.999 + sqrt(1.001^2 + 1e-8)) / 2.
  #' @description Test that a catch larger than the biomass gives an expected depletion at the smooth floor near 0.001.
  expect_equal(
    object = exp(get_report(fit)[["log_expected_depletion"]][1]),
    expected = (-0.999 + sqrt(1.001^2 + 1e-8)) / 2
  )
  #' @description Test that the negative log-likelihood is finite when the catch is larger than the biomass.
  expect_true(is.finite(get_report(fit)[["jnll"]]))

  # A missing index year is left out of q and of the likelihood. The index
  # in the other years is q times biomass, so q is still 0.5.
  missing_index_data <- dplyr::filter(
    small_data,
    !(type == "index" & timing == 2002)
  )
  report <- small_parameters |>
    initialize_fims(data = FIMSFrame(missing_index_data)) |>
    fit_fims(optimize = FALSE) |>
    get_report()
  #' @description Test that catchability is 0.5 when a year without an index is left out.
  expect_equal(
    object = report[["catchability"]][[2]],
    expected = 0.5
  )

  # With 2 index values, 1 with an sd of 0.1 and 1 with an sd of 0.2, log q is
  # the mean of log(I / B) weighted by 1 / sd^2: (100 * log(0.6) + 25 *
  # log(0.4)) / 125.
  weighted_data <- small_data |>
    dplyr::filter(!(type == "index" & timing == 2003)) |>
    dplyr::mutate(
      observed = dplyr::case_when(
        type == "index" & timing == 2001 ~ 0.6 * 100,
        type == "index" & timing == 2002 ~ 0.4 * 90,
        .default = observed
      ),
      uncertainty = dplyr::if_else(
        type == "index" & timing == 2001,
        "~ dlnorm(meanlog = log_index_expected, sdlog = 0.1)",
        uncertainty
      )
    )
  report <- small_parameters |>
    initialize_fims(data = FIMSFrame(weighted_data)) |>
    fit_fims(optimize = FALSE) |>
    get_report()
  #' @description Test that log catchability is the mean of log(index / biomass) weighted by 1 / sd^2.
  expect_equal(
    object = log(report[["catchability"]][[2]]),
    expected = (100 * log(0.6) + 25 * log(0.4)) / 125
  )

  # Catch-at-age data, here data_big, has data the surplus production model
  # does not use.
  big_frame <- FIMSFrame(data_big)
  #' @description Test that `initialize_fims()` says which data a surplus production model does not use.
  expect_message(
    object = setup_default_parameters(
      big_frame,
      model_type = "SurplusProduction"
    ) |>
      initialize_fims(data = big_frame),
    regexp = "does not use"
  )
})

## Error handling ----
test_that("`surplus_production()` data checks return correct error messages", {
  missing_catch_data <- dplyr::filter(
    small_data,
    !(type == "catch" & timing == 2002)
  )
  #' @description Test that `initialize_fims()` errors when the catch of a year is missing.
  expect_error(
    object = initialize_fims(small_parameters, FIMSFrame(missing_catch_data)),
    regexp = "catch is missing"
  )

  normal_index_data <- dplyr::mutate(
    small_data,
    uncertainty = dplyr::if_else(
      type == "index",
      "~ dnorm(mean = index_expected, sd = 1)",
      uncertainty
    )
  )
  #' @description Test that `initialize_fims()` errors when an index is not lognormal.
  expect_error(
    object = initialize_fims(small_parameters, FIMSFrame(normal_index_data)),
    regexp = "is not lognormal"
  )

  natural_scale_link_data <- dplyr::mutate(
    small_data,
    uncertainty = dplyr::if_else(
      type == "index",
      "~ dlnorm(meanlog = index_expected, sdlog = 0.2)",
      uncertainty
    )
  )
  #' @description Test that `initialize_fims()` errors when a lognormal index is not linked to log_index_expected.
  expect_error(
    object = initialize_fims(
      small_parameters, FIMSFrame(natural_scale_link_data)
    ),
    regexp = "is not lognormal on"
  )

  two_unit_data <- dplyr::bind_rows(
    small_data,
    dplyr::filter(small_data, type == "catch") |>
      dplyr::mutate(fleet = "fleet2", unit = "number")
  )
  #' @description Test that `initialize_fims()` errors when the catch data are in more than 1 unit.
  expect_error(
    object = initialize_fims(small_parameters, FIMSFrame(two_unit_data)),
    regexp = "catch data are in 2 units"
  )
})

test_that("`initialize_fims()` errors on parameter rows a surplus production model does not use", {
  log_q_row <- tibble::tibble(
    module_name = "Fleet", fleet = "survey1", label = "log_q",
    value = 0, estimation_type = "constant"
  )
  #' @description Test that `initialize_fims()` errors on a Fleet row, which a surplus production model does not use.
  expect_error(
    object = initialize_fims(
      dplyr::bind_rows(small_parameters, log_q_row), small_frame
    ),
    regexp = "does not use the\\s+parameter"
  )
  misspelled_row <- tibble::tibble(
    module_name = "Data", fleet = "survey1", label = "index_logsd",
    value = log(0.3), estimation_type = "constant"
  )
  #' @description Test that `initialize_fims()` errors on a Data row that matches no index parameter.
  expect_error(
    object = initialize_fims(
      dplyr::bind_rows(small_parameters, misspelled_row), small_frame
    ),
    regexp = "does not use the\\s+parameter"
  )
  index_log_sd_row <- dplyr::mutate(misspelled_row, label = "index_log_sd")
  #' @description Test that `initialize_fims()` accepts the Data row for the index log sd.
  expect_no_error(
    initialize_fims(
      dplyr::bind_rows(small_parameters, index_log_sd_row), small_frame
    )
  )
})

test_that("`initialize_fims()` errors when log_depletion does not cover the 2nd model year to the last", {
  # Depletion in the first year is the initial depletion, so log_depletion
  # starts in the 2nd model year.
  depletion_from_year_1 <- dplyr::mutate(
    small_parameters,
    timing = dplyr::if_else(label == "log_depletion", timing - 1, timing)
  )
  #' @description Test that `initialize_fims()` errors for log_depletion from the first model year, which is the initial depletion.
  expect_error(
    object = initialize_fims(depletion_from_year_1, small_frame),
    regexp = "Depletion in the first year is the\\s+initial\\s+depletion"
  )
  missing_year <- dplyr::filter(
    small_parameters,
    !(label == "log_depletion" & timing == 2003)
  )
  #' @description Test that `initialize_fims()` errors for log_depletion with a missing year.
  expect_error(
    object = initialize_fims(missing_year, small_frame),
    regexp = "needs rows for each year from the 2nd model\\s+year"
  )
})
